CREATE TABLE IF NOT EXISTS users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, username VARCHAR(100) UNIQUE NOT NULL, email VARCHAR(255) NULL UNIQUE, display_name VARCHAR(150) NOT NULL DEFAULT '', password_hash VARCHAR(255) NOT NULL, role ENUM('admin','user') NOT NULL DEFAULT 'admin', is_active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS albums (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, owner_user_id INT UNSIGNED NULL, title VARCHAR(255) NOT NULL, artist VARCHAR(255) DEFAULT '', album_artist VARCHAR(180) NOT NULL DEFAULT '', release_year INT UNSIGNED NULL, genre VARCHAR(150) NOT NULL DEFAULT '', label_name VARCHAR(180) NOT NULL DEFAULT '', copyright_text VARCHAR(255) NOT NULL DEFAULT '', description TEXT, cover_file VARCHAR(255), deleted_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS tracks (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, album_id INT UNSIGNED NOT NULL, title VARCHAR(255) NOT NULL, disc_no INT UNSIGNED NOT NULL DEFAULT 1, track_no INT UNSIGNED DEFAULT 0, audio_file VARCHAR(255) NOT NULL, original_name VARCHAR(255) NOT NULL, file_size BIGINT UNSIGNED DEFAULT 0, duration_seconds INT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_tracks_album FOREIGN KEY(album_id) REFERENCES albums(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS shares (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, album_id INT UNSIGNED NOT NULL, token CHAR(48) UNIQUE NOT NULL, label VARCHAR(255) DEFAULT '', password_hash VARCHAR(255) NULL, expires_at DATETIME NULL, allow_download TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_shares_album FOREIGN KEY(album_id) REFERENCES albums(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS settings (setting_key VARCHAR(100) PRIMARY KEY, setting_value TEXT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS album_collaborators (album_id INT UNSIGNED NOT NULL, user_id INT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(album_id,user_id), CONSTRAINT fk_album_collab_album FOREIGN KEY(album_id) REFERENCES albums(id) ON DELETE CASCADE, CONSTRAINT fk_album_collab_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS statistics_daily (event_date DATE NOT NULL, album_id INT UNSIGNED NOT NULL, share_id INT UNSIGNED NOT NULL DEFAULT 0, track_id INT UNSIGNED NOT NULL DEFAULT 0, event_type ENUM('album_view','track_play','track_download','album_download') NOT NULL, event_count BIGINT UNSIGNED NOT NULL DEFAULT 0, PRIMARY KEY(event_date,album_id,share_id,track_id,event_type), KEY idx_stats_album_date(album_id,event_date), KEY idx_stats_type_date(event_type,event_date)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS password_reset_tokens (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,expires_at DATETIME NOT NULL,used_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,KEY idx_password_reset_user(user_id),KEY idx_password_reset_expiry(expires_at),CONSTRAINT fk_password_reset_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS login_attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,login_key CHAR(64) NOT NULL,attempted_at DATETIME NOT NULL,successful TINYINT(1) NOT NULL DEFAULT 0,KEY idx_login_attempts_key_time(login_key,attempted_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS user_sessions (session_token CHAR(64) PRIMARY KEY,user_id INT UNSIGNED NOT NULL,created_at DATETIME NOT NULL,last_seen_at DATETIME NOT NULL,expires_at DATETIME NOT NULL,revoked_at DATETIME NULL,ip_hint VARCHAR(64) NOT NULL DEFAULT '',user_agent_hint VARCHAR(255) NOT NULL DEFAULT '',KEY idx_user_sessions_user(user_id,last_seen_at),CONSTRAINT fk_user_sessions_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
